export type RoleApp = { role: string; key: string; host: Host; capabilities: { name: string; route: string | null; state: CapState }[] };
export const ROLE_APPS: RoleApp[] = ROLE_APP_ROWS.map(([role, key, host, caps]) => ({ role, key, host, capabilities: caps.map(([name, route, state]) => ({ name, route, state })) }));
export const roleAppByKey = (k: string) => ROLE_APPS.find((a) => a.key === k) ?? null;

/** Apps a membership role opens today. Finer roles come from the 79-role templates, which are proposed and grant nothing yet,
 *  so only these coarse mappings are live. An unknown role opens nothing (deny by default). */
const ROLE_TO_APPS: Record<string, string[]> = {
  Student: ['student', 'undergraduate-student', 'graduate-student'], Faculty: ['faculty'], Advisor: ['academic-advisor'], Tutor: ['tutor'],
  Staff: ['university-staff', 'registrar', 'student-accounts-officer', 'career-center-staff', 'disability-services-staff', 'learning-center-staff', 'financial-aid-officer'],
  Administrator: ['university-admin', 'integration-admin', 'data-steward', 'moderator'], Alumni: ['alumni'], Employer: ['employer'],
};
/** The membership role an app acts as. Used to scope authority to the active app; unknown app = no role. */
export const roleForApp = (key: string): string | null => Object.entries(ROLE_TO_APPS).find(([, ks]) => ks.includes(key))?.[0] ?? null;
export const appsForRoles = (roles: string[]) => [...new Set(roles.flatMap((r) => ROLE_TO_APPS[r] ?? []))].map((k) => roleAppByKey(k)!).filter(Boolean);

export function gapStats(apps: RoleApp[] = ROLE_APPS) {
  const all = apps.flatMap((a) => a.capabilities);
  const count = (s: CapState) => all.filter((c) => c.state === s).length;
  return { apps: apps.length, capabilities: all.length, existing: count('existing'), incomplete: count('incomplete'), missing: count('missing') };
}
